// src/components/MainPage.js
import React from 'react';
import styled from 'styled-components';

const MainContainer = styled.div`
  text-align: center;
  padding: 40px;
`;

const HeroSection = styled.div`
  background-color: #f4f4f9;
  padding: 60px 20px;
  margin-bottom: 40px;
`;

const HeroTitle = styled.h1`
  font-size: 3.5rem;
  color: #264653;
  margin-bottom: 20px;
`;

const HeroSubtitle = styled.p`
  font-size: 1.5rem;
  color: #2a9d8f;
  margin-bottom: 20px;
`;

const ImagePlaceholder = styled.img`
  width: 80%;
  height: auto;
  border-radius: 10px;
  margin-top: 20px;
  margin-bottom: 40px;
  object-fit: cover;
`;

const SectionTitle = styled.h2`
  font-size: 2.5rem;
  color: #1d3557;
  margin-top: 40px;
`;

const ContentParagraph = styled.p`
  font-size: 1.2rem;
  color: #333;
  margin-bottom: 20px;
  text-align: left;
  line-height: 1.8;
  max-width: 800px;
  margin: 0 auto;
`;

const InfoList = styled.ul`
  text-align: left;
  max-width: 800px;
  margin: 20px auto;
  list-style-type: square;
`;

const InfoListItem = styled.li`
  font-size: 1.2rem;
  color: #1d3557;
  margin-bottom: 10px;
`;

const MainPage = () => {
  return (
    <MainContainer>
      <HeroSection>
        <HeroTitle>Welcome to TriGear</HeroTitle>
        <HeroSubtitle>Your ultimate guide for Triathlon and Ironman competitions</HeroSubtitle>
        {/* Placeholder Image */}
        <ImagePlaceholder src="https://images.squarespace-cdn.com/content/v1/61b7d0c4c5a10d1c445590cf/1639436551704-BT7W6EV3J6LRPR2VZL21/Drew+Placid+Finish+Hero.jpeg?format=1500w" alt="Triathlon Hero Image" />
      </HeroSection>

      <SectionTitle>The History of Triathlon and Ironman</SectionTitle>
      <ContentParagraph>
        The sport of triathlon was born in the 1970s in Southern California and has evolved into one of the most challenging endurance events. The concept was simple: combine three sports (swimming, cycling, and running) into one long race. The first official Ironman Triathlon was held in 1978 in Hawaii, and it consisted of a 2.4-mile swim, a 112-mile bike ride, and a marathon (26.2 miles) run.
      </ContentParagraph>
      <ContentParagraph>
        Today, triathlons are held all over the world, with distances ranging from Sprint (shorter distances) to the full Ironman races. Triathlon is now a popular Olympic sport and continues to grow in popularity across all age groups and abilities.
      </ContentParagraph>

      {/* Placeholder Image */}
      <ImagePlaceholder src="https://kajabi-storefronts-production.kajabi-cdn.com/kajabi-storefronts-production/blogs/34705/images/Vt9lOElaRmum3AkvGvuu_brief_hisotry_blog.png" alt="Triathlon History Image" />

      <SectionTitle>Beginner Advice: How to Get Started</SectionTitle>
      <ContentParagraph>
        Starting your triathlon journey can seem daunting, but it doesn’t have to be! Follow these key steps to ease into the sport:
      </ContentParagraph>
      <InfoList>
        <InfoListItem><strong>Start Small:</strong> Choose a sprint triathlon or a shorter distance to begin with.</InfoListItem>
        <InfoListItem><strong>Training Plan:</strong> Focus on balanced training across all three disciplines—swimming, biking, and running.</InfoListItem>
        <InfoListItem><strong>Get the Right Gear:</strong> Invest in basic, quality gear such as a road bike, running shoes, and a tri-suit. You don’t need to spend a fortune at the beginning.</InfoListItem>
        <InfoListItem><strong>Practice Transitions:</strong> Get comfortable with the transition between swimming to biking (T1) and biking to running (T2). Efficiency here can save you valuable time.</InfoListItem>
        <InfoListItem><strong>Join a Community:</strong> Find local triathlete groups or online forums to stay motivated and learn from others’ experiences.</InfoListItem>
      </InfoList>

      <SectionTitle>Common Misconceptions About Triathlon</SectionTitle>
      <ContentParagraph>
        There are several myths and misconceptions surrounding triathlons, especially for beginners. Let’s clear some of those up:
      </ContentParagraph>
      <InfoList>
        <InfoListItem><strong>"You need a top-tier bike to compete":</strong> While a good bike is important, beginners can complete triathlons on any decent road bike. You don't need to splurge on a high-end model at first.</InfoListItem>
        <InfoListItem><strong>"Triathletes are superhumans":</strong> Absolutely not! Triathlon welcomes athletes of all abilities, from weekend warriors to seasoned pros. Everyone can find a race that fits their fitness level.</InfoListItem>
        <InfoListItem><strong>"You have to be an expert in all three sports":</strong> Many triathletes come from one discipline (like running) and improve their weaker areas over time. The goal is improvement, not perfection.</InfoListItem>
      </InfoList>

      {/* Placeholder Image */}
      <ImagePlaceholder src="https://websitedevsa.blob.core.windows.net/sitefinity/images/default-source/events/2021-open-water-nationals/genericopenwater885x544.jpg?sfvrsn=5e093732_0&size=1220" alt="Common Misconceptions Image" />

      <SectionTitle>Essential Gear You Need on Race Day</SectionTitle>
      <ContentParagraph>
        Race day can be both exciting and nerve-wracking. Here’s a checklist of the essentials you need to bring:
      </ContentParagraph>
      <InfoList>
        <InfoListItem><strong>Triathlon Suit:</strong> A tri-suit will keep you comfortable across all three disciplines without needing to change clothes.</InfoListItem>
        <InfoListItem><strong>Bike:</strong> Your road or triathlon bike, along with a helmet, is essential. Make sure your bike is in good working condition.</InfoListItem>
        <InfoListItem><strong>Running Shoes:</strong> A good pair of running shoes can make all the difference in the final leg of the race.</InfoListItem>
        <InfoListItem><strong>Swimming Gear:</strong> Don’t forget your goggles, swim cap, and wetsuit (if required for cold water).</InfoListItem>
        <InfoListItem><strong>Hydration & Nutrition:</strong> Energy gels, water bottles, and electrolytes are key for keeping your energy levels stable throughout the race.</InfoListItem>
        <InfoListItem><strong>Sunglasses & Hat:</strong> Protect yourself from the sun during the bike and run portions.</InfoListItem>
      </InfoList>

      {/* Placeholder Image */}
      <ImagePlaceholder src="https://via.placeholder.com/800x400" alt="Race Day Essentials Image" />

      <SectionTitle>Get Inspired!</SectionTitle>
      <ContentParagraph>
        Every triathlete has a different journey, but they all share one common goal: crossing the finish line. Get inspired by watching some of the best moments from Ironman and triathlon races around the world.
      </ContentParagraph>

      {/* Placeholder Video Section */}
      <ImagePlaceholder src="https://via.placeholder.com/800x400" alt="Inspiration Video Placeholder" />

      <SectionTitle>Join the Community</SectionTitle>
      <ContentParagraph>
        Triathlon is not just a sport—it’s a community. Whether you’re a beginner or a seasoned athlete, there’s always someone to train with, race against, or learn from. Join the global triathlon community and start your journey today!
      </ContentParagraph>
    </MainContainer>
  );
};

export default MainPage;
